import java.util.*;
final class Cfg {
    static final class Block {
        final int number, start;
        int end;
        final List<String> labels;
        final List<Integer> instructions = new ArrayList<>(), predecessors = new ArrayList<>(),
                            successors = new ArrayList<>();
        Block(int number, List<String> labels, int start) {
            this.number = number;
            this.labels = List.copyOf(labels);
            this.start = start;
        }
    }
    static final class Loop {
        final int header;
        final List<Integer> latches;
        final Set<Integer> blocks, exits = new TreeSet<>(), outside = new TreeSet<>();
        int depth;
        Loop(int header, List<Integer> latches, Set<Integer> blocks) {
            this.header = header;
            this.latches = latches;
            this.blocks = blocks;
        }
    }
    final TacParser.Function function;
    final TreeMap<Integer, Block> blocks = new TreeMap<>();
    final TreeMap<Integer, TacParser.Instruction> instructions = new TreeMap<>();
    final Map<Integer, Integer> positions = new HashMap<>(), blockOf = new HashMap<>(),
                                immediate = new HashMap<>(), depth = new HashMap<>();
    final Set<Integer> reachable = new TreeSet<>();
    final List<Integer> postorder = new ArrayList<>(), reversePostorder = new ArrayList<>();
    final Map<Integer, List<Integer>> reachablePredecessors = new HashMap<>();
    final Map<Integer, Set<Integer>> dominators = new HashMap<>();
    final List<Loop> loops = new ArrayList<>();
    Cfg(TacParser.Function function) {
        this.function = function;
        split();
        connect();
        visit(1);
        reversePostorder.addAll(postorder);
        Collections.reverse(reversePostorder);
        for (int number : reachable) {
            List<Integer> predecessors = new ArrayList<>();
            for (int predecessor : blocks.get(number).predecessors)
                if (reachable.contains(predecessor))
                    predecessors.add(predecessor);
            reachablePredecessors.put(number, predecessors);
        }
        dominance();
        loops();
    }
    void split() {
        List<String> pending = new ArrayList<>();
        int firstLabel = 0;
        Block current = null;
        TacParser.Kind previous = null;
        for (int index = 0; index < function.code.size(); index++) {
            TacParser.Line line = function.code.get(index);
            if (line instanceof TacParser.Label label) {
                if (pending.isEmpty())
                    firstLabel = index;
                pending.add(label.name());
                continue;
            }
            TacParser.Instruction instruction = (TacParser.Instruction)line;
            int number = instructions.size() + 1;
            if (current == null || !pending.isEmpty() || previous == TacParser.Kind.GOTO ||
                previous == TacParser.Kind.IF || previous == TacParser.Kind.RETURN) {
                int start = pending.isEmpty() ? index : firstLabel;
                if (current != null)
                    current.end = start;
                current = new Block(blocks.size() + 1, pending, start);
                blocks.put(current.number, current);
                pending.clear();
            }
            instructions.put(number, instruction);
            positions.put(number, index);
            blockOf.put(number, current.number);
            current.instructions.add(number);
            previous = instruction.kind();
        }
        current.end = function.code.size();
    }
    void connect() {
        Map<String, Integer> labels = new HashMap<>();
        for (Block block : blocks.values())
            for (String label : block.labels)
                labels.put(label, block.number);
        for (Block block : blocks.values()) {
            TacParser.Instruction last = instructions.get(block.instructions.getLast());
            if (last.kind() == TacParser.Kind.GOTO)
                block.successors.add(labels.get(last.name()));
            else if (last.kind() == TacParser.Kind.IF) {
                block.successors.add(block.number + 1);
                int target = labels.get(last.name());
                if (target != block.number + 1)
                    block.successors.add(target);
            } else if (last.kind() != TacParser.Kind.RETURN)
                block.successors.add(block.number + 1);
            for (int successor : block.successors)
                blocks.get(successor).predecessors.add(block.number);
        }
    }
    void visit(int number) {
        reachable.add(number);
        for (int successor : blocks.get(number).successors)
            if (!reachable.contains(successor))
                visit(successor);
        postorder.add(number);
    }
    void dominance() {
        for (int number : reachable)
            dominators.put(number, new HashSet<>(reachable));
        dominators.put(1, new HashSet<>(Set.of(1)));
        boolean changed;
        do {
            changed = false;
            for (int number : reversePostorder.subList(1, reversePostorder.size())) {
                List<Integer> predecessors = reachablePredecessors.get(number);
                Set<Integer> value = new HashSet<>(dominators.get(predecessors.getFirst()));
                for (int predecessor : predecessors)
                    value.retainAll(dominators.get(predecessor));
                value.add(number);
                if (!value.equals(dominators.get(number))) {
                    dominators.put(number, value);
                    changed = true;
                }
            }
        } while (changed);
        for (int number : reachable)
            if (number != 1) {
                int parent = 0;
                for (int candidate : dominators.get(number))
                    if (candidate != number && (parent == 0 || dominators.get(candidate).size() >
                                                                   dominators.get(parent).size()))
                        parent = candidate;
                immediate.put(number, parent);
            }
    }
    void loops() {
        for (int header : reachable) {
            List<Integer> latches = new ArrayList<>();
            for (int number : reachablePredecessors.get(header))
                if (dominators.get(number).contains(header))
                    latches.add(number);
            if (latches.isEmpty())
                continue;
            Set<Integer> members = new TreeSet<>();
            members.add(header);
            members.addAll(latches);
            Deque<Integer> pending = new ArrayDeque<>();
            for (int latch : latches)
                if (latch != header)
                    pending.push(latch);
            while (!pending.isEmpty()) {
                int number = pending.pop();
                for (int predecessor : reachablePredecessors.get(number))
                    if (members.add(predecessor))
                        pending.push(predecessor);
            }
            loops.add(new Loop(header, latches, members));
        }
        for (int number : blocks.keySet()) {
            int count = 0;
            for (Loop loop : loops)
                if (loop.blocks.contains(number))
                    count++;
            depth.put(number, count);
        }
        for (Loop loop : loops) {
            for (Loop other : loops)
                if (other.blocks.contains(loop.header))
                    loop.depth++;
            for (int number : loop.blocks) {
                Block block = blocks.get(number);
                boolean exit = false;
                for (int successor : block.successors)
                    if (!loop.blocks.contains(successor)) {
                        loop.outside.add(successor);
                        exit = true;
                    }
                if (exit ||
                    instructions.get(block.instructions.getLast()).kind() == TacParser.Kind.RETURN)
                    loop.exits.add(number);
            }
        }
    }
}

import java.util.*;
final class Dataflow {
    record Definition(String variable, int number) {}
    record Copy(String destination, String source) {}
    interface Transfer<T> {
        Set<T> apply(TacParser.Instruction instruction, int number, Set<T> state);
    }
    record
        Solution<T>(Map<Integer, Set<T>> incoming, Map<Integer, Set<T>> outgoing, int iterations) {}
    final Cfg graph;
    final Solution<Definition> reaching;
    final Solution<String> live;
    final Solution<TacParser.Expression> expressions;
    final Solution<Copy> copies;
    final Map<Integer, Set<Definition>> reachingBefore;
    final Map<Integer, Set<TacParser.Expression>> expressionBefore;
    final Map<Integer, Set<Copy>> copyBefore;
    final Map<Integer, Set<String>> liveBefore = new HashMap<>(), liveAfter = new HashMap<>();
    static Set<Definition> reachingTransfer(TacParser.Instruction instruction, int number,
                                            Set<Definition> state) {
        Set<Definition> result = new HashSet<>(state);
        if (instruction.destination() != null) {
            result.removeIf(definition -> definition.variable().equals(instruction.destination()));
            result.add(new Definition(instruction.destination(), number));
        }
        return result;
    }
    static Set<String> liveTransfer(TacParser.Instruction instruction, Set<String> state) {
        Set<String> result = new HashSet<>(state);
        result.remove(instruction.destination());
        result.addAll(instruction.used());
        return result;
    }
    static Set<TacParser.Expression> expressionTransfer(TacParser.Instruction instruction,
                                                        int number,
                                                        Set<TacParser.Expression> state) {
        Set<TacParser.Expression> result = new HashSet<>(state);
        TacParser.Expression expression = instruction.expression();
        if (expression != null)
            result.add(expression);
        if (instruction.kind() == TacParser.Kind.STORE)
            result.removeIf(
                e -> e.kind() == TacParser.Kind.LOAD && e.operation().equals(instruction.name()));
        if (instruction.kind() == TacParser.Kind.CALL)
            result.removeIf(e -> e.kind() == TacParser.Kind.LOAD);
        if (instruction.destination() != null) {
            TacParser.Variable variable = new TacParser.Variable(instruction.destination());
            result.removeIf(e -> variable.equals(e.a()) || variable.equals(e.b()));
        }
        return result;
    }
    static Set<Copy> copyTransfer(TacParser.Instruction instruction, int number, Set<Copy> state) {
        Set<Copy> result = new HashSet<>(state);
        String destination = instruction.destination();
        if (destination != null)
            result.removeIf(copy
                            -> copy.destination().equals(destination) ||
                                   copy.source().equals(destination));
        if (instruction.kind() == TacParser.Kind.COPY &&
            instruction.a() instanceof TacParser.Variable source &&
            !source.name().equals(destination))
            result.add(new Copy(destination, source.name()));
        return result;
    }
    Dataflow(Cfg graph) {
        this.graph = graph;
        Set<TacParser.Expression> expressionUniverse = new HashSet<>();
        Set<Copy> copyUniverse = new HashSet<>();
        Set<Definition> parameters = new HashSet<>();
        for (String parameter : graph.function.parameters)
            parameters.add(new Definition(parameter, 0));
        for (var entry : graph.instructions.entrySet())
            if (graph.reachable.contains(graph.blockOf.get(entry.getKey()))) {
                TacParser.Instruction instruction = entry.getValue();
                if (instruction.expression() != null)
                    expressionUniverse.add(instruction.expression());
                if (instruction.kind() == TacParser.Kind.COPY &&
                    instruction.a() instanceof TacParser.Variable source &&
                    !source.name().equals(instruction.destination()))
                    copyUniverse.add(new Copy(instruction.destination(), source.name()));
            }
        reaching = forward(true, Set.of(), parameters, Dataflow::reachingTransfer);
        live = liveness();
        expressions = forward(false, expressionUniverse, Set.of(), Dataflow::expressionTransfer);
        copies = forward(false, copyUniverse, Set.of(), Dataflow::copyTransfer);
        reachingBefore = boundaries(reaching.incoming(), Dataflow::reachingTransfer);
        expressionBefore = boundaries(expressions.incoming(), Dataflow::expressionTransfer);
        copyBefore = boundaries(copies.incoming(), Dataflow::copyTransfer);
        for (int block : graph.reachable) {
            Set<String> state = new HashSet<>(live.outgoing().get(block));
            List<Integer> numbers = graph.blocks.get(block).instructions;
            for (int i = numbers.size() - 1; i >= 0; i--) {
                int number = numbers.get(i);
                liveAfter.put(number, new HashSet<>(state));
                state = liveTransfer(graph.instructions.get(number), state);
                liveBefore.put(number, new HashSet<>(state));
            }
        }
    }
    <T> Solution<T> forward(boolean union, Set<T> universe, Set<T> entry, Transfer<T> transfer) {
        Map<Integer, Set<T>> incoming = new HashMap<>(), outgoing = new HashMap<>();
        for (int block : graph.reachable)
            outgoing.put(block, new HashSet<>(universe));
        int iterations = 0;
        while (true) {
            iterations++;
            boolean changed = false;
            for (int number : graph.reversePostorder) {
                List<Integer> predecessors = graph.reachablePredecessors.get(number);
                Set<T> state = new HashSet<>();
                if (union) {
                    for (int predecessor : predecessors)
                        state.addAll(outgoing.get(predecessor));
                    if (number == 1)
                        state.addAll(entry);
                } else if (number != 1) {
                    state.addAll(outgoing.get(predecessors.getFirst()));
                    for (int predecessor : predecessors)
                        state.retainAll(outgoing.get(predecessor));
                }
                incoming.put(number, new HashSet<>(state));
                for (int instruction : graph.blocks.get(number).instructions)
                    state = transfer.apply(graph.instructions.get(instruction), instruction, state);
                if (!state.equals(outgoing.get(number))) {
                    outgoing.put(number, state);
                    changed = true;
                }
            }
            if (!changed)
                return new Solution<>(incoming, outgoing, iterations);
        }
    }
    Solution<String> liveness() {
        Map<Integer, Set<String>> incoming = new HashMap<>(), outgoing = new HashMap<>();
        for (int number : graph.reachable)
            incoming.put(number, new HashSet<>());
        int iterations = 0;
        while (true) {
            iterations++;
            boolean changed = false;
            for (int number : graph.postorder) {
                Set<String> state = new HashSet<>();
                for (int successor : graph.blocks.get(number).successors)
                    state.addAll(incoming.get(successor));
                outgoing.put(number, new HashSet<>(state));
                List<Integer> instructions = graph.blocks.get(number).instructions;
                for (int i = instructions.size() - 1; i >= 0; i--)
                    state = liveTransfer(graph.instructions.get(instructions.get(i)), state);
                if (!state.equals(incoming.get(number))) {
                    incoming.put(number, state);
                    changed = true;
                }
            }
            if (!changed)
                return new Solution<>(incoming, outgoing, iterations);
        }
    }
    <T> Map<Integer, Set<T>> boundaries(Map<Integer, Set<T>> incoming, Transfer<T> transfer) {
        Map<Integer, Set<T>> result = new HashMap<>();
        for (int block : graph.reachable) {
            Set<T> state = new HashSet<>(incoming.get(block));
            for (int number : graph.blocks.get(block).instructions) {
                result.put(number, new HashSet<>(state));
                state = transfer.apply(graph.instructions.get(number), number, state);
            }
        }
        return result;
    }
}

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import java.util.function.Function;
public final class Main {
    static final List<String> PASS_ORDER = List.of("constprop", "copyprop", "cse", "dce", "licm",
                                                   "unreachable"),
                              VERSIONS = List.of("original", "optimized", "allocated");
    static String list(Collection<?> values) {
        return values.isEmpty() ? "-"
                                : String.join(",", values.stream().map(Object::toString).toList());
    }
    static String blocks(Collection<Integer> numbers) {
        return list(numbers.stream().map(number -> "B" + number).toList());
    }
    static String instructions(Collection<Integer> numbers) {
        return list(numbers.stream().map(number -> "#" + number).toList());
    }
    record Settings(int registers, List<String> enabled, int rounds) {}
    static Settings settings(String text) {
        List<String> lines = text.lines().toList();
        int registers = Integer.parseInt(lines.get(0).split(" ")[1]),
            rounds = Integer.parseInt(lines.get(2).split(" ")[1]);
        Set<String> enabled = new HashSet<>(Arrays.asList(lines.get(1).split(" ")));
        return new Settings(registers, PASS_ORDER.stream().filter(enabled::contains).toList(),
                            rounds);
    }
    static List<List<Integer>> runs(String text) {
        List<String> lines = text.lines().toList();
        List<List<Integer>> result = new ArrayList<>();
        for (int i = 1; i <= Integer.parseInt(lines.getFirst()); i++) {
            String[] words = lines.get(i).split(" +");
            List<Integer> values = new ArrayList<>();
            for (int j = 1; j <= Integer.parseInt(words[0]); j++)
                values.add(Integer.parseInt(words[j]));
            result.add(values);
        }
        return result;
    }
    static List<Integer> reachableInstructions(Cfg graph) {
        return graph.instructions.keySet()
            .stream()
            .filter(number -> graph.reachable.contains(graph.blockOf.get(number)))
            .toList();
    }
    static Set<Integer> reachingNumbers(Dataflow flow, int number, String variable) {
        Set<Integer> result = new TreeSet<>();
        for (Dataflow.Definition definition : flow.reachingBefore.get(number))
            if (definition.variable().equals(variable))
                result.add(definition.number());
        return result;
    }
    static Integer constantValue(Cfg graph, Set<Integer> definitions) {
        if (definitions.isEmpty() || definitions.contains(0))
            return null;
        Integer value = null;
        for (int number : definitions) {
            TacParser.Instruction instruction = graph.instructions.get(number);
            if (instruction.kind() != TacParser.Kind.COPY ||
                !(instruction.a() instanceof TacParser.Constant constant))
                return null;
            if (value != null && value != constant.value())
                return null;
            value = constant.value();
        }
        return value;
    }
    record PassResult(int count, List<String> records) {}
    static PassResult constantPropagation(TacParser.Function function, Cfg graph, Dataflow flow) {
        Map<Integer, List<TacParser.Line>> replacements = new HashMap<>();
        List<String> records = new ArrayList<>();
        for (int number : reachableInstructions(graph)) {
            TacParser.Instruction original = graph.instructions.get(number), instruction = original;
            for (int field : original.operandFields())
                if (original.operand(field) instanceof TacParser.Variable variable) {
                    Integer value =
                        constantValue(graph, reachingNumbers(flow, number, variable.name()));
                    if (value != null) {
                        instruction = instruction.withOperand(field, new TacParser.Constant(value));
                        records.add("#" + number + ": " + variable.name() + " -> " + value);
                    }
                }
            TacParser.Instruction result = Optimizations.fold(instruction);
            if (result == null) {
                records.add("#" + number + ": delete " + instruction);
                replacements.put(number, List.of());
            } else {
                if (result != instruction)
                    records.add("#" + number + ": fold " + result);
                replacements.put(number, List.of(result));
            }
        }
        Optimizations.rewrite(function, replacements);
        return new PassResult(records.size(), records);
    }
    static PassResult copyPropagation(TacParser.Function function, Cfg graph, Dataflow flow) {
        Map<Integer, List<TacParser.Line>> replacements = new HashMap<>();
        List<String> records = new ArrayList<>();
        for (int number : reachableInstructions(graph)) {
            TacParser.Instruction original = graph.instructions.get(number), instruction = original;
            Map<String, String> available = new HashMap<>();
            for (Dataflow.Copy copy : flow.copyBefore.get(number))
                available.put(copy.destination(), copy.source());
            for (int field : original.operandFields())
                if (original.operand(field) instanceof TacParser.Variable variable &&
                    available.containsKey(variable.name())) {
                    String replacement = available.get(variable.name());
                    instruction =
                        instruction.withOperand(field, new TacParser.Variable(replacement));
                    records.add("#" + number + ": " + variable.name() + " -> " + replacement);
                }
            replacements.put(number, List.of(instruction));
        }
        Optimizations.rewrite(function, replacements);
        return new PassResult(records.size(), records);
    }
    static Set<Integer> expressionSources(Cfg graph, TacParser.Expression expression,
                                          int candidate) {
        int blockNumber = graph.blockOf.get(candidate);
        List<Integer> numbers = graph.blocks.get(blockNumber).instructions;
        for (int i = numbers.size() - 1; i >= 0; i--) {
            int number = numbers.get(i);
            if (number < candidate &&
                expression.equals(graph.instructions.get(number).expression()))
                return Set.of(number);
        }
        Set<Integer> sources = new TreeSet<>(), examined = new HashSet<>();
        Deque<Integer> pending = new ArrayDeque<>(graph.reachablePredecessors.get(blockNumber));
        while (!pending.isEmpty()) {
            int number = pending.pop();
            if (!examined.add(number))
                continue;
            List<Integer> block = graph.blocks.get(number).instructions;
            boolean found = false;
            for (int i = block.size() - 1; i >= 0; i--) {
                int instruction = block.get(i);
                if (expression.equals(graph.instructions.get(instruction).expression())) {
                    sources.add(instruction);
                    found = true;
                    break;
                }
            }
            if (!found)
                pending.addAll(graph.reachablePredecessors.get(number));
        }
        return sources;
    }
    static PassResult commonSubexpressions(TacParser.Function function, Cfg graph, Dataflow flow) {
        Map<TacParser.Expression, List<Integer>> candidates = new LinkedHashMap<>();
        for (int number : reachableInstructions(graph)) {
            TacParser.Expression expression = graph.instructions.get(number).expression();
            if (expression != null && flow.expressionBefore.get(number).contains(expression))
                candidates.computeIfAbsent(expression, key -> new ArrayList<>()).add(number);
        }
        Map<Integer, List<TacParser.Line>> replacements = new HashMap<>();
        List<String> records = new ArrayList<>();
        int changes = 0;
        for (var entry : candidates.entrySet()) {
            TacParser.Expression expression = entry.getKey();
            List<Integer> numbers = entry.getValue();
            Set<Integer> sources = new TreeSet<>();
            for (int number : numbers)
                sources.addAll(expressionSources(graph, expression, number));
            sources.removeAll(numbers);
            Optimizations.CseEdits edits = Optimizations.cse(function, graph, sources, numbers);
            replacements.putAll(edits.replacements());
            records.add(expression + ": " + edits.temporary() +
                        " sources=" + instructions(sources) + " replaced=" + instructions(numbers));
            changes += numbers.size();
        }
        Optimizations.rewrite(function, replacements);
        return new PassResult(changes, records);
    }
    static PassResult deadCode(TacParser.Function function, Cfg graph, Dataflow flow) {
        Map<Integer, List<TacParser.Line>> replacements = new HashMap<>();
        TreeMap<Integer, String> records = new TreeMap<>();
        for (int block : graph.reachable) {
            Set<String> state = new HashSet<>(flow.live.outgoing().get(block));
            List<Integer> numbers = graph.blocks.get(block).instructions;
            for (int i = numbers.size() - 1; i >= 0; i--) {
                int number = numbers.get(i);
                TacParser.Instruction instruction = graph.instructions.get(number);
                String destination = instruction.destination();
                boolean selfCopy = instruction.kind() == TacParser.Kind.COPY &&
                                   instruction.a() instanceof TacParser.Variable variable &&
                                   variable.name().equals(destination);
                boolean dead = Set.of(TacParser.Kind.COPY, TacParser.Kind.BIN, TacParser.Kind.LOAD)
                                   .contains(instruction.kind()) &&
                               !state.contains(destination);
                if (selfCopy || dead) {
                    replacements.put(number, List.of());
                    records.put(number, "#" + number + ": delete " + instruction);
                    continue;
                }
                if (instruction.kind() == TacParser.Kind.CALL && destination != null &&
                    !state.contains(destination)) {
                    records.put(number, "#" + number + ": unused result " + instruction);
                    instruction = instruction.withDestination(null);
                    replacements.put(number, List.of(instruction));
                }
                state = Dataflow.liveTransfer(instruction, state);
            }
        }
        Optimizations.rewrite(function, replacements);
        return new PassResult(records.size(), new ArrayList<>(records.values()));
    }
    static Set<Integer> inside(Cfg graph, Cfg.Loop loop, Set<Integer> definitions) {
        Set<Integer> result = new HashSet<>();
        for (int number : definitions)
            if (number != 0 && loop.blocks.contains(graph.blockOf.get(number)))
                result.add(number);
        return result;
    }
    static List<Integer> markedInvariants(Cfg graph, Dataflow flow, Cfg.Loop loop,
                                          List<Integer> numbers) {
        Set<String> stores = new HashSet<>();
        boolean calls = false;
        for (int number : numbers) {
            TacParser.Instruction instruction = graph.instructions.get(number);
            if (instruction.kind() == TacParser.Kind.STORE)
                stores.add(instruction.name());
            if (instruction.kind() == TacParser.Kind.CALL)
                calls = true;
        }
        Set<Integer> marked = new HashSet<>();
        List<Integer> order = new ArrayList<>();
        while (true) {
            boolean changed = false;
            for (int number : numbers) {
                TacParser.Instruction instruction = graph.instructions.get(number);
                if (marked.contains(number) ||
                    !Set.of(TacParser.Kind.COPY, TacParser.Kind.BIN, TacParser.Kind.LOAD)
                         .contains(instruction.kind()))
                    continue;
                if (instruction.kind() == TacParser.Kind.LOAD &&
                    (calls || stores.contains(instruction.name())))
                    continue;
                boolean invariant = true;
                for (String variable : instruction.used()) {
                    Set<Integer> definitions = reachingNumbers(flow, number, variable),
                                 inside = inside(graph, loop, definitions);
                    if (!inside.isEmpty() &&
                        !(definitions.size() == 1 && marked.containsAll(inside))) {
                        invariant = false;
                        break;
                    }
                }
                if (invariant) {
                    marked.add(number);
                    order.add(number);
                    changed = true;
                }
            }
            if (!changed)
                return order;
        }
    }
    static List<Integer> movableInvariants(Cfg graph, Dataflow flow, Cfg.Loop loop,
                                           List<Integer> numbers, List<Integer> marked) {
        Map<String, Integer> definitions = new HashMap<>();
        for (int number : numbers) {
            String destination = graph.instructions.get(number).destination();
            if (destination != null)
                definitions.merge(destination, 1, Integer::sum);
        }
        Set<Integer> moved = new HashSet<>();
        List<Integer> order = new ArrayList<>();
        for (int number : marked) {
            TacParser.Instruction instruction = graph.instructions.get(number);
            String destination = instruction.destination();
            if (definitions.get(destination) != 1 ||
                flow.live.incoming().get(loop.header).contains(destination))
                continue;
            int block = graph.blockOf.get(number);
            boolean dominatesExits = true;
            for (int exit : loop.exits)
                if (!graph.dominators.get(exit).contains(block))
                    dominatesExits = false;
            boolean dangerous =
                instruction.kind() == TacParser.Kind.LOAD ||
                instruction.kind() == TacParser.Kind.BIN &&
                    (instruction.operation().equals("/") || instruction.operation().equals("%")) &&
                    (instruction.b() instanceof TacParser.Variable ||
                     Optimizations.constant(instruction.b(), 0));
            boolean deadOutside = true;
            for (int successor : loop.outside)
                if (flow.live.incoming().get(successor).contains(destination))
                    deadOutside = false;
            if (!dominatesExits && (dangerous || !deadOutside))
                continue;
            boolean ready = true;
            for (String variable : instruction.used())
                if (!moved.containsAll(
                        inside(graph, loop, reachingNumbers(flow, number, variable))))
                    ready = false;
            if (ready) {
                moved.add(number);
                order.add(number);
            }
        }
        return order;
    }
    static PassResult invariantMotion(TacParser.Function function, Cfg graph, Dataflow flow) {
        List<Cfg.Loop> loops = new ArrayList<>(graph.loops);
        loops.sort(Comparator.comparingInt((Cfg.Loop loop) -> loop.blocks.size())
                       .thenComparingInt(loop -> loop.header));
        for (Cfg.Loop loop : loops) {
            List<Integer> numbers = new ArrayList<>();
            for (int block : loop.blocks)
                numbers.addAll(graph.blocks.get(block).instructions);
            Collections.sort(numbers);
            List<Integer> moves = movableInvariants(graph, flow, loop, numbers,
                                                    markedInvariants(graph, flow, loop, numbers));
            if (!moves.isEmpty()) {
                String destination = Optimizations.hoist(function, graph, loop, moves);
                return new PassResult(moves.size(),
                                      List.of("B" + loop.header + ": hoist " + instructions(moves) +
                                              " to " + destination));
            }
        }
        return new PassResult(0, List.of());
    }
    static PassResult unreachable(TacParser.Function function, Cfg graph) {
        Optimizations.Removal removal = Optimizations.removeUnreachable(function, graph);
        List<String> records = new ArrayList<>();
        for (int block : removal.blocks())
            records.add("remove block B" + block);
        for (int number : removal.jumps())
            records.add("remove jump #" + number);
        for (String label : removal.labels())
            records.add("remove label " + label);
        return new PassResult(records.size(), records);
    }
    static List<String> optimize(TacParser.Function function, Settings settings,
                                 Map<String, Integer> totals) {
        int before = function.instructions().size(), round = 0;
        List<String> result = new ArrayList<>(List.of("== " + function.name + " =="));
        for (int r = 1; r <= settings.rounds(); r++) {
            round = r;
            List<String> counts = new ArrayList<>(), records = new ArrayList<>();
            boolean changed = false;
            for (String name : settings.enabled()) {
                Cfg graph = new Cfg(function);
                Dataflow flow = new Dataflow(graph);
                PassResult pass = switch (name) {
                    case "constprop" -> constantPropagation(function, graph, flow);
                    case "copyprop" -> copyPropagation(function, graph, flow);
                    case "cse" -> commonSubexpressions(function, graph, flow);
                    case "dce" -> deadCode(function, graph, flow);
                    case "licm" -> invariantMotion(function, graph, flow);
                    default -> unreachable(function, graph);
                };
                counts.add(name + "=" + pass.count());
                totals.merge(name, pass.count(), Integer::sum);
                changed |= pass.count() != 0;
                for (String record : pass.records())
                    records.add("  " + name + " " + record);
            }
            result.add("round " + round + ": " + String.join(" ", counts));
            result.addAll(records);
            if (!changed)
                break;
        }
        result.add("result: rounds=" + round + " instructions=" + before + "->" +
                   function.instructions().size());
        return result;
    }
    record
        CallGraph(Map<String, List<String>> callees, Set<String> reachable, Set<String> recursive) {
    }
    static Set<String> reach(Collection<String> starts, Map<String, List<String>> callees) {
        Set<String> result = new HashSet<>();
        Deque<String> pending = new ArrayDeque<>(starts);
        while (!pending.isEmpty()) {
            String name = pending.pop();
            if (result.add(name))
                pending.addAll(callees.get(name));
        }
        return result;
    }
    static CallGraph callGraph(TacParser.Program program) {
        List<String> names = program.functions().stream().map(function -> function.name).toList();
        Map<String, List<String>> callees = new HashMap<>();
        for (TacParser.Function function : program.functions()) {
            Set<String> called = new HashSet<>();
            for (TacParser.Instruction instruction : function.instructions())
                if (instruction.kind() == TacParser.Kind.CALL)
                    called.add(instruction.name());
            callees.put(function.name, names.stream().filter(called::contains).toList());
        }
        Set<String> recursive = new HashSet<>();
        for (String name : names)
            if (reach(callees.get(name), callees).contains(name))
                recursive.add(name);
        return new CallGraph(callees, reach(List.of("main"), callees), recursive);
    }
    static List<String> callGraphLines(TacParser.Program program, String heading, CallGraph graph) {
        List<String> result = new ArrayList<>(List.of("== call graph (" + heading + ") =="));
        for (TacParser.Function function : program.functions())
            result.add(function.name + " -> " + list(graph.callees().get(function.name)) +
                       (graph.recursive().contains(function.name) ? " (recursive)" : ""));
        result.add("unreachable functions: " +
                   list(program.functions()
                            .stream()
                            .map(function -> function.name)
                            .filter(name -> !graph.reachable().contains(name))
                            .toList()));
        return result;
    }
    static String definitions(Set<Dataflow.Definition> values) {
        return list(values.stream()
                        .sorted(Comparator.comparingInt(Dataflow.Definition::number)
                                    .thenComparing(Dataflow.Definition::variable))
                        .map(definition -> definition.variable() + ":" + definition.number())
                        .toList());
    }
    static <T> void analysisSets(List<String> lines, String title, Dataflow.Solution<T> solution,
                                 Cfg graph, Function<Set<T>, String> render) {
        lines.add(title + ": iterations=" + solution.iterations());
        for (int block : graph.reachable)
            lines.add("B" + block + " in=" + render.apply(solution.incoming().get(block)) +
                      " out=" + render.apply(solution.outgoing().get(block)));
    }
    static void tree(List<String> lines, Cfg graph, int number, int depth) {
        lines.add("  ".repeat(depth) + "B" + number);
        for (int child : graph.reachable)
            if (Objects.equals(graph.immediate.get(child), number))
                tree(lines, graph, child, depth + 1);
    }
    static List<String> analysis(TacParser.Function function, String heading) {
        Cfg graph = new Cfg(function);
        Dataflow flow = new Dataflow(graph);
        List<String> result =
            new ArrayList<>(List.of("== " + function.name + " (" + heading + ") ==", "code:"));
        int number = 0;
        for (TacParser.Line line : function.code) {
            if (line instanceof TacParser.Label label) {
                result.add(label.name() + ":");
                continue;
            }
            TacParser.Instruction instruction = (TacParser.Instruction)line;
            number++;
            String text = "  #" + number + " " + instruction;
            if (graph.reachable.contains(graph.blockOf.get(number))) {
                List<String> chains = new ArrayList<>();
                for (String variable : new LinkedHashSet<>(instruction.used()))
                    chains.add(variable + ":" + list(reachingNumbers(flow, number, variable)));
                if (!chains.isEmpty())
                    text += " | " + String.join(" ", chains);
            }
            result.add(text);
        }
        result.add("blocks: " + graph.blocks.size());
        for (Cfg.Block block : graph.blocks.values())
            result.add("B" + block.number + " " + block.instructions.getFirst() + "-" +
                       block.instructions.getLast() + " labels=" + list(block.labels) + " preds=" +
                       blocks(block.predecessors) + " succs=" + blocks(block.successors));
        Set<Integer> unreachable = new TreeSet<>(graph.blocks.keySet());
        unreachable.removeAll(graph.reachable);
        result.add("unreachable: " + blocks(unreachable));
        result.add("order: " + blocks(graph.reversePostorder));
        result.add("dominators:");
        for (int block : graph.reachable)
            result.add("B" + block +
                       " idom=" + (block == 1 ? "-" : "B" + graph.immediate.get(block)) +
                       " dom=" + blocks(new TreeSet<>(graph.dominators.get(block))));
        result.add("dominator tree:");
        tree(result, graph, 1, 0);
        result.add("loops: " + graph.loops.size());
        for (Cfg.Loop loop : graph.loops)
            result.add("header=B" + loop.header + " latches=" + blocks(loop.latches) +
                       " depth=" + loop.depth + " blocks=" + blocks(loop.blocks) +
                       " exits=" + blocks(loop.exits));
        analysisSets(result, "reaching definitions", flow.reaching, graph, Main::definitions);
        analysisSets(result, "liveness", flow.live, graph, values -> list(new TreeSet<>(values)));
        analysisSets(result, "available expressions", flow.expressions, graph,
                     values -> list(values.stream().map(Object::toString).sorted().toList()));
        return result;
    }
    record Rewritten(TacParser.Function function, int moves) {}
    static TacParser.Operand rename(TacParser.Operand operand, Map<String, Integer> colors) {
        return operand instanceof TacParser.Variable variable && colors.containsKey(variable.name())
            ? new TacParser.Variable("R" + colors.get(variable.name()))
            : operand;
    }
    static Rewritten registers(TacParser.Function function, Map<String, Integer> colors) {
        List<TacParser.Line> code = new ArrayList<>();
        int moves = 0;
        for (TacParser.Line line : function.code) {
            if (line instanceof TacParser.Label) {
                code.add(line);
                continue;
            }
            TacParser.Instruction instruction = (TacParser.Instruction)line;
            if (instruction.destination() != null && colors.containsKey(instruction.destination()))
                instruction =
                    instruction.withDestination("R" + colors.get(instruction.destination()));
            for (int field : instruction.operandFields())
                instruction =
                    instruction.withOperand(field, rename(instruction.operand(field), colors));
            if (instruction.kind() == TacParser.Kind.COPY &&
                instruction.a() instanceof TacParser.Variable variable &&
                variable.name().equals(instruction.destination()))
                moves++;
            else
                code.add(instruction);
        }
        List<String> parameters =
            function.parameters.stream()
                .map(name -> colors.containsKey(name) ? "R" + colors.get(name) : name)
                .toList();
        return new Rewritten(new TacParser.Function(function.name, parameters, code), moves);
    }
    record AllocationReport(TacParser.Function function, List<String> lines) {}
    static AllocationReport allocation(TacParser.Function function, int registers) {
        Cfg graph = new Cfg(function);
        Dataflow flow = new Dataflow(graph);
        Regalloc allocation = new Regalloc(function, graph, flow, registers);
        Rewritten rewritten = registers(function, allocation.colors);
        int edges = allocation.neighbors.values().stream().mapToInt(Set::size).sum() / 2;
        List<String> result = new ArrayList<>(List.of(
            "== " + function.name + " ==", "nodes=" + allocation.neighbors.size() +
                                               " edges=" + edges + " registers=" + registers));
        for (var entry : allocation.neighbors.entrySet())
            result.add(entry.getKey() + " degree=" + entry.getValue().size() +
                       " cost=" + allocation.costs.get(entry.getKey()) +
                       " neighbors=" + list(entry.getValue()));
        result.add("simplify: " + list(allocation.order));
        result.add(
            "potential spills: " +
            list(allocation.potential.stream()
                     .map(potential
                          -> potential.node() + "(" + allocation.costs.get(potential.node()) + "/" +
                                 potential.degree() + ")")
                     .toList()));
        for (String node : allocation.neighbors.keySet())
            result.add(node + " -> " +
                       (allocation.colors.containsKey(node) ? "R" + allocation.colors.get(node)
                                                            : "spill"));
        int pressure = 0;
        for (Set<String> state : flow.liveBefore.values())
            pressure = Math.max(pressure, state.size());
        for (Set<String> state : flow.liveAfter.values())
            pressure = Math.max(pressure, state.size());
        int spillUses = 0, spillDefinitions = 0;
        for (TacParser.Instruction instruction : function.instructions()) {
            for (String variable : instruction.used())
                if (allocation.spills.contains(variable))
                    spillUses++;
            if (allocation.spills.contains(instruction.destination()))
                spillDefinitions++;
        }
        for (String parameter : function.parameters)
            if (allocation.spills.contains(parameter))
                spillDefinitions++;
        result.add("summary: pressure=" + pressure +
                   " used=" + new HashSet<>(allocation.colors.values()).size() +
                   " spilled=" + allocation.spills.size() + " moves=" + rewritten.moves() +
                   " spill_uses=" + spillUses + " spill_defs=" + spillDefinitions);
        result.addAll(TacParser.functionLines(rewritten.function()));
        return new AllocationReport(rewritten.function(), result);
    }
    record Executable(List<String> parameters, List<TacParser.Instruction> instructions,
                      Map<String, Integer> labels) {}
    static final class Interpreter {
        final Map<String, Executable> functions = new HashMap<>();
        final Map<String, int[]> arrays = new HashMap<>();
        final List<Integer> inputs, output = new ArrayList<>();
        final Map<String, Integer> steps = new HashMap<>(), calls = new HashMap<>();
        final EnumMap<TacParser.Kind, Integer> kinds = new EnumMap<>(TacParser.Kind.class);
        int inputIndex;
        Interpreter(TacParser.Program program, List<Integer> inputs) {
            this.inputs = inputs;
            for (TacParser.Function function : program.functions()) {
                Map<String, Integer> labels = new HashMap<>();
                List<TacParser.Instruction> instructions = new ArrayList<>();
                for (TacParser.Line line : function.code)
                    if (line instanceof TacParser.Label label)
                        labels.put(label.name(), instructions.size());
                    else
                        instructions.add((TacParser.Instruction)line);
                functions.put(function.name,
                              new Executable(function.parameters, instructions, labels));
            }
            for (TacParser.Array array : program.arrays())
                arrays.put(array.name(), new int[array.size()]);
        }
        int value(TacParser.Operand operand, Map<String, Integer> variables) {
            return operand instanceof TacParser.Constant constant
                ? constant.value()
                : variables.get(((TacParser.Variable)operand).name());
        }
        Integer call(String name, List<Integer> arguments) {
            Executable function = functions.get(name);
            Map<String, Integer> variables = new HashMap<>();
            for (int i = 0; i < function.parameters().size(); i++)
                variables.put(function.parameters().get(i), arguments.get(i));
            List<Integer> pushed = new ArrayList<>();
            int position = 0;
            calls.merge(name, 1, Integer::sum);
            while (true) {
                TacParser.Instruction instruction = function.instructions().get(position++);
                steps.merge(name, 1, Integer::sum);
                kinds.merge(instruction.kind(), 1, Integer::sum);
                switch (instruction.kind()) {
                case COPY ->
                    variables.put(instruction.destination(), value(instruction.a(), variables));
                case BIN ->
                    variables.put(instruction.destination(),
                                  (int)TacParser.calculate(instruction.operation(),
                                                           value(instruction.a(), variables),
                                                           value(instruction.b(), variables)));
                case LOAD ->
                    variables.put(
                        instruction.destination(),
                        arrays.get(instruction.name())[value(instruction.a(), variables)]);
                case STORE ->
                    arrays.get(instruction.name())[value(instruction.a(), variables)] =
                        value(instruction.b(), variables);
                case GOTO -> position = function.labels().get(instruction.name());
                case IF -> {
                    if (TacParser.calculate(instruction.operation(),
                                            value(instruction.a(), variables),
                                            value(instruction.b(), variables)) != 0)
                        position = function.labels().get(instruction.name());
                }
                case PARAM -> pushed.add(value(instruction.a(), variables));
                case CALL -> {
                    int first = pushed.size() - instruction.count();
                    List<Integer> values = new ArrayList<>(pushed.subList(first, pushed.size()));
                    pushed.subList(first, pushed.size()).clear();
                    Integer returned = call(instruction.name(), values);
                    if (instruction.destination() != null)
                        variables.put(instruction.destination(), returned);
                }
                case RETURN -> {
                    return instruction.a() == null ? null : value(instruction.a(), variables);
                }
                case READ -> variables.put(instruction.destination(), inputs.get(inputIndex++));
                case PRINT -> output.add(value(instruction.a(), variables));
                }
            }
        }
    }
    static EnumMap<TacParser.Kind, Integer> staticKinds(TacParser.Program program) {
        EnumMap<TacParser.Kind, Integer> result = new EnumMap<>(TacParser.Kind.class);
        for (TacParser.Function function : program.functions())
            for (TacParser.Instruction instruction : function.instructions())
                result.merge(instruction.kind(), 1, Integer::sum);
        return result;
    }
    static int sum(Map<?, Integer> values) {
        return values.values().stream().mapToInt(Integer::intValue).sum();
    }
    static <K> void addCounts(Map<K, Integer> destination, Map<K, Integer> source) {
        for (var entry : source.entrySet())
            destination.merge(entry.getKey(), entry.getValue(), Integer::sum);
    }
    static List<String> comparison(TacParser.Program original, TacParser.Program optimized,
                                   TacParser.Program allocated, List<List<Integer>> runs) {
        List<TacParser.Program> programs = List.of(original, optimized, allocated);
        List<Map<String, Integer>> profiles = new ArrayList<>();
        List<EnumMap<TacParser.Kind, Integer>> dynamic = new ArrayList<>();
        for (int i = 0; i < 3; i++) {
            profiles.add(new HashMap<>());
            dynamic.add(new EnumMap<>(TacParser.Kind.class));
        }
        int[] totalSteps = new int[3];
        Map<String, Integer> originalCalls = new HashMap<>();
        List<String> result = new ArrayList<>();
        int same = 0;
        for (int r = 0; r < runs.size(); r++) {
            List<Integer> inputs = runs.get(r);
            result.add("run " + (r + 1) + ": inputs=" + inputs.size());
            List<List<Integer>> outputs = new ArrayList<>();
            for (int version = 0; version < 3; version++) {
                Interpreter interpreter = new Interpreter(programs.get(version), inputs);
                interpreter.call("main", List.of());
                int steps = sum(interpreter.steps), calls = sum(interpreter.calls);
                result.add("  " + VERSIONS.get(version) + ": steps=" + steps + " calls=" + calls +
                           " output=" + list(interpreter.output));
                addCounts(profiles.get(version), interpreter.steps);
                addCounts(dynamic.get(version), interpreter.kinds);
                totalSteps[version] += steps;
                if (version == 0)
                    addCounts(originalCalls, interpreter.calls);
                outputs.add(interpreter.output);
            }
            boolean equal =
                outputs.get(0).equals(outputs.get(1)) && outputs.get(1).equals(outputs.get(2));
            if (equal)
                same++;
            result.add("  result: " + (equal ? "same" : "different"));
        }
        result.add("== profile ==");
        for (TacParser.Function function : original.functions()) {
            String name = function.name;
            result.add(name + ": calls=" + originalCalls.getOrDefault(name, 0) +
                       " original=" + profiles.get(0).getOrDefault(name, 0) +
                       " optimized=" + profiles.get(1).getOrDefault(name, 0) +
                       " allocated=" + profiles.get(2).getOrDefault(name, 0));
        }
        EnumMap<TacParser.Kind, Integer> originalKinds = staticKinds(original),
                                         optimizedKinds = staticKinds(optimized);
        result.add("== summary ==");
        result.add("runs=" + runs.size() + " same=" + same + " different=" + (runs.size() - same));
        result.add("instructions: original=" + sum(originalKinds) +
                   " optimized=" + sum(optimizedKinds));
        List<String> counts = new ArrayList<>();
        for (TacParser.Kind kind : TacParser.Kind.values())
            counts.add(kind + "=" + originalKinds.getOrDefault(kind, 0) + "->" +
                       optimizedKinds.getOrDefault(kind, 0));
        result.add("kinds: " + String.join(" ", counts));
        counts.clear();
        for (int version = 0; version < 3; version++)
            counts.add(VERSIONS.get(version) + "=" + totalSteps[version]);
        result.add("steps: " + String.join(" ", counts));
        for (int version = 0; version < 3; version++) {
            counts = new ArrayList<>();
            for (TacParser.Kind kind : TacParser.Kind.values())
                counts.add(kind + "=" + dynamic.get(version).getOrDefault(kind, 0));
            result.add("dynamic " + VERSIONS.get(version) + ": " + String.join(" ", counts));
        }
        return result;
    }
    static String read(String name) throws IOException {
        return Files.readString(Path.of("input", name), StandardCharsets.US_ASCII);
    }
    static void write(String name, List<String> lines) throws IOException {
        Files.writeString(Path.of("output", name), String.join("\n", lines) + "\n",
                          StandardCharsets.US_ASCII);
    }
    public static void main(String[] args) throws IOException {
        Settings settings = settings(read("params.txt"));
        List<List<Integer>> runs = runs(read("input.txt"));
        TacParser.Program original = TacParser.parse(read("program.tac"));
        List<String> analysis = callGraphLines(original, "original", callGraph(original));
        for (TacParser.Function function : original.functions())
            analysis.addAll(analysis(function, "original"));
        TacParser.Program working = new TacParser.Program(
            original.arrays(),
            original.functions().stream().map(TacParser.Function::copy).toList());
        List<String> passes = new ArrayList<>();
        Map<String, Integer> totals = new HashMap<>();
        for (TacParser.Function function : working.functions())
            passes.addAll(optimize(function, settings, totals));
        CallGraph graph = callGraph(working);
        analysis.addAll(callGraphLines(working, "optimized", graph));
        List<String> removed = working.functions()
                                   .stream()
                                   .map(function -> function.name)
                                   .filter(name
                                           -> settings.enabled().contains("unreachable") &&
                                                  !graph.reachable().contains(name))
                                   .toList();
        TacParser.Program optimized = new TacParser.Program(
            working.arrays(), working.functions()
                                  .stream()
                                  .filter(function -> !removed.contains(function.name))
                                  .toList());
        passes.add("== program ==");
        passes.add("removed functions: " + list(removed));
        passes.add("== total ==");
        passes.add(String.join(" ", settings.enabled()
                                        .stream()
                                        .map(name -> name + "=" + totals.getOrDefault(name, 0))
                                        .toList()));
        List<TacParser.Function> allocatedFunctions = new ArrayList<>();
        List<String> regalloc = new ArrayList<>();
        for (TacParser.Function function : optimized.functions()) {
            analysis.addAll(analysis(function, "optimized"));
            AllocationReport allocation = allocation(function, settings.registers());
            allocatedFunctions.add(allocation.function());
            regalloc.addAll(allocation.lines());
        }
        TacParser.Program allocated = new TacParser.Program(optimized.arrays(), allocatedFunctions);
        Files.createDirectories(Path.of("output"));
        write("optimized.tac", TacParser.programLines(optimized));
        write("analysis.txt", analysis);
        write("passes.txt", passes);
        write("regalloc.txt", regalloc);
        write("comparison.txt", comparison(original, optimized, allocated, runs));
    }
}

import java.util.*;
final class Optimizations {
    static void rewrite(TacParser.Function function,
                        Map<Integer, List<TacParser.Line>> replacements,
                        Map<Integer, List<TacParser.Line>> insertions) {
        List<TacParser.Line> result = new ArrayList<>();
        int number = 0;
        for (int index = 0; index < function.code.size(); index++) {
            result.addAll(insertions.getOrDefault(index, List.of()));
            TacParser.Line line = function.code.get(index);
            if (line instanceof TacParser.Label)
                result.add(line);
            else
                result.addAll(replacements.getOrDefault(++number, List.of(line)));
        }
        result.addAll(insertions.getOrDefault(function.code.size(), List.of()));
        function.code = result;
    }
    static void rewrite(TacParser.Function function,
                        Map<Integer, List<TacParser.Line>> replacements) {
        rewrite(function, replacements, Map.of());
    }
    static boolean constant(TacParser.Operand operand, int value) {
        return operand instanceof TacParser.Constant c && c.value() == value;
    }
    static TacParser.Instruction fold(TacParser.Instruction instruction) {
        if (instruction.kind() != TacParser.Kind.BIN && instruction.kind() != TacParser.Kind.IF)
            return instruction;
        TacParser.Operand first = instruction.a(), second = instruction.b();
        boolean a = first instanceof TacParser.Constant, b = second instanceof TacParser.Constant;
        if (a && b) {
            int x = ((TacParser.Constant)first).value(), y = ((TacParser.Constant)second).value();
            if ((instruction.operation().equals("/") || instruction.operation().equals("%")) &&
                y == 0)
                return instruction;
            long result = TacParser.calculate(instruction.operation(), x, y);
            if (instruction.kind() == TacParser.Kind.IF)
                return result != 0 ? new TacParser.Instruction(TacParser.Kind.GOTO, null, null,
                                                               null, null, instruction.name(), 0)
                                   : null;
            if (result >= Integer.MIN_VALUE && result <= Integer.MAX_VALUE)
                return TacParser.copy(instruction.destination(),
                                      new TacParser.Constant((int)result));
            return instruction;
        }
        if (instruction.kind() != TacParser.Kind.BIN || a == b)
            return instruction;
        TacParser.Operand replacement = null;
        String op = instruction.operation();
        if (op.equals("+") && (constant(first, 0) || constant(second, 0)))
            replacement = a ? second : first;
        else if (op.equals("-") && constant(second, 0))
            replacement = first;
        else if (op.equals("*") && (constant(first, 1) || constant(second, 1)))
            replacement = a ? second : first;
        else if (op.equals("/") && constant(second, 1))
            replacement = first;
        else if (op.equals("*") && (constant(first, 0) || constant(second, 0)))
            replacement = new TacParser.Constant(0);
        return replacement == null ? instruction
                                   : TacParser.copy(instruction.destination(), replacement);
    }
    record CseEdits(String temporary, Map<Integer, List<TacParser.Line>> replacements) {}
    static CseEdits cse(TacParser.Function function, Cfg graph, Set<Integer> sources,
                        List<Integer> candidates) {
        String temporary = "_t" + (++function.temporarySerial);
        Map<Integer, List<TacParser.Line>> result = new HashMap<>();
        for (int number : sources) {
            TacParser.Instruction instruction = graph.instructions.get(number);
            result.put(number, List.of(instruction.withDestination(temporary),
                                       TacParser.copy(instruction.destination(),
                                                      new TacParser.Variable(temporary))));
        }
        for (int number : candidates)
            result.put(number, List.of(TacParser.copy(graph.instructions.get(number).destination(),
                                                      new TacParser.Variable(temporary))));
        return new CseEdits(temporary, result);
    }
    static String hoist(TacParser.Function function, Cfg graph, Cfg.Loop loop,
                        List<Integer> moves) {
        Cfg.Block header = graph.blocks.get(loop.header);
        List<Integer> outside = new ArrayList<>();
        for (int number : header.predecessors)
            if (!loop.blocks.contains(number))
                outside.add(number);
        Map<Integer, List<TacParser.Line>> replacements = new HashMap<>();
        List<TacParser.Line> instructions = new ArrayList<>();
        for (int number : moves) {
            replacements.put(number, List.of());
            instructions.add(graph.instructions.get(number));
        }
        int position;
        String destination;
        List<TacParser.Line> insertion;
        if (loop.header != 1 && outside.size() == 1 &&
            graph.blocks.get(outside.getFirst()).successors.equals(List.of(loop.header))) {
            Cfg.Block preheader = graph.blocks.get(outside.getFirst());
            int last = preheader.instructions.getLast();
            position = graph.positions.get(last);
            TacParser.Kind kind = graph.instructions.get(last).kind();
            if (kind != TacParser.Kind.GOTO && kind != TacParser.Kind.IF)
                position++;
            insertion = instructions;
            destination = "B" + preheader.number;
        } else {
            String label = "_p" + (++function.preheaderSerial);
            position = header.start;
            insertion = new ArrayList<>();
            insertion.add(new TacParser.Label(label));
            insertion.addAll(instructions);
            destination = "new " + label;
            for (int number : outside) {
                int last = graph.blocks.get(number).instructions.getLast();
                TacParser.Instruction instruction = graph.instructions.get(last);
                if ((instruction.kind() == TacParser.Kind.GOTO ||
                     instruction.kind() == TacParser.Kind.IF) &&
                    header.labels.contains(instruction.name()))
                    replacements.put(last, List.of(instruction.withName(label)));
            }
        }
        rewrite(function, replacements, Map.of(position, insertion));
        return destination;
    }
    record Removal(List<Integer> blocks, List<Integer> jumps, List<String> labels) {}
    record NumberedLine(TacParser.Line line, Integer number) {}
    static Removal removeUnreachable(TacParser.Function function, Cfg graph) {
        List<Integer> removedBlocks = new ArrayList<>(), jumps = new ArrayList<>();
        Set<Integer> deleted = new HashSet<>();
        for (Cfg.Block block : graph.blocks.values())
            if (!graph.reachable.contains(block.number)) {
                removedBlocks.add(block.number);
                for (int i = block.start; i < block.end; i++)
                    deleted.add(i);
            }
        Map<Integer, Integer> numbers = new HashMap<>();
        for (var entry : graph.positions.entrySet())
            numbers.put(entry.getValue(), entry.getKey());
        List<NumberedLine> remaining = new ArrayList<>();
        for (int i = 0; i < function.code.size(); i++)
            if (!deleted.contains(i))
                remaining.add(new NumberedLine(function.code.get(i), numbers.get(i)));
        for (int i = 0; i < remaining.size(); i++)
            if (remaining.get(i).line() instanceof TacParser.Instruction instruction &&
                (instruction.kind() == TacParser.Kind.GOTO ||
                 instruction.kind() == TacParser.Kind.IF)) {
                for (int next = i + 1; next < remaining.size() &&
                                       remaining.get(next).line() instanceof TacParser.Label;
                     next++)
                    if (((TacParser.Label)remaining.get(next).line())
                            .name()
                            .equals(instruction.name())) {
                        jumps.add(remaining.get(i).number());
                        break;
                    }
            }
        Set<Integer> removedJumps = new HashSet<>(jumps);
        remaining.removeIf(line -> removedJumps.contains(line.number()));
        Set<String> targets = new HashSet<>();
        for (NumberedLine line : remaining)
            if (line.line() instanceof TacParser.Instruction instruction &&
                (instruction.kind() == TacParser.Kind.GOTO ||
                 instruction.kind() == TacParser.Kind.IF))
                targets.add(instruction.name());
        List<String> labels = new ArrayList<>();
        List<TacParser.Line> code = new ArrayList<>();
        for (NumberedLine line : remaining) {
            if (line.line() instanceof TacParser.Label label && !targets.contains(label.name()))
                labels.add(label.name());
            else
                code.add(line.line());
        }
        function.code = code;
        return new Removal(removedBlocks, jumps, labels);
    }
}

import java.math.BigInteger;
import java.util.*;
final class Regalloc {
    record Potential(String node, int degree) {}
    final TreeMap<String, Set<String>> neighbors = new TreeMap<>();
    final Map<String, BigInteger> costs = new HashMap<>();
    final Map<String, Set<String>> partners = new HashMap<>();
    final List<String> order = new ArrayList<>();
    final List<Potential> potential = new ArrayList<>();
    final Map<String, Integer> colors = new HashMap<>();
    final Set<String> spills = new HashSet<>();
    Regalloc(TacParser.Function function, Cfg graph, Dataflow flow, int registers) {
        Set<String> nodes = new TreeSet<>(function.parameters);
        for (var entry : graph.instructions.entrySet())
            if (graph.reachable.contains(graph.blockOf.get(entry.getKey()))) {
                TacParser.Instruction instruction = entry.getValue();
                nodes.addAll(instruction.used());
                if (instruction.destination() != null)
                    nodes.add(instruction.destination());
            }
        for (String node : nodes) {
            neighbors.put(node, new TreeSet<>());
            costs.put(node, BigInteger.ZERO);
            partners.put(node, new HashSet<>());
        }
        for (int blockNumber : graph.reachable) {
            Cfg.Block block = graph.blocks.get(blockNumber);
            Set<String> state = new HashSet<>(flow.live.outgoing().get(blockNumber));
            for (int i = block.instructions.size() - 1; i >= 0; i--) {
                TacParser.Instruction instruction =
                    graph.instructions.get(block.instructions.get(i));
                String destination = instruction.destination();
                if (destination != null) {
                    String partner = instruction.kind() == TacParser.Kind.COPY &&
                                             instruction.a() instanceof TacParser.Variable v
                                         ? v.name()
                                         : null;
                    for (String variable : state)
                        if (!variable.equals(destination) && !variable.equals(partner))
                            edge(destination, variable);
                }
                state = Dataflow.liveTransfer(instruction, state);
            }
            BigInteger weight = BigInteger.TEN.pow(graph.depth.get(blockNumber));
            for (int number : block.instructions) {
                TacParser.Instruction instruction = graph.instructions.get(number);
                List<String> occurrences = instruction.used();
                if (instruction.destination() != null)
                    occurrences.add(instruction.destination());
                for (String variable : occurrences)
                    costs.put(variable, costs.get(variable).add(weight));
            }
        }
        Set<String> entry = new HashSet<>(flow.live.incoming().get(1));
        entry.addAll(function.parameters);
        for (String parameter : function.parameters) {
            costs.put(parameter, costs.get(parameter).add(BigInteger.ONE));
            for (String variable : entry)
                if (!variable.equals(parameter))
                    edge(parameter, variable);
        }
        for (TacParser.Instruction instruction : function.instructions())
            if (instruction.kind() == TacParser.Kind.COPY &&
                instruction.a() instanceof TacParser.Variable v &&
                !v.name().equals(instruction.destination())) {
                String first = instruction.destination(), second = v.name();
                if (partners.containsKey(first))
                    partners.get(first).add(second);
                if (partners.containsKey(second))
                    partners.get(second).add(first);
            }
        Set<String> remaining = new TreeSet<>(nodes);
        while (!remaining.isEmpty()) {
            Map<String, Integer> degrees = new HashMap<>();
            for (String node : remaining) {
                int degree = 0;
                for (String neighbor : neighbors.get(node))
                    if (remaining.contains(neighbor))
                        degree++;
                degrees.put(node, degree);
            }
            String chosen = null;
            for (String node : remaining)
                if (degrees.get(node) < registers &&
                    (chosen == null || degrees.get(node) < degrees.get(chosen)))
                    chosen = node;
            if (chosen == null) {
                for (String node : remaining)
                    if (chosen == null || costs.get(node)
                                                  .multiply(BigInteger.valueOf(degrees.get(chosen)))
                                                  .compareTo(costs.get(chosen).multiply(
                                                      BigInteger.valueOf(degrees.get(node)))) < 0)
                        chosen = node;
                potential.add(new Potential(chosen, degrees.get(chosen)));
            }
            order.add(chosen);
            remaining.remove(chosen);
        }
        for (int i = order.size() - 1; i >= 0; i--) {
            String node = order.get(i);
            TreeSet<Integer> free = new TreeSet<>();
            for (int register = 0; register < registers; register ++)
                free.add(register);
            for (String neighbor : neighbors.get(node))
                if (colors.containsKey(neighbor))
                    free.remove(colors.get(neighbor));
            if (free.isEmpty()) {
                spills.add(node);
                continue;
            }
            TreeSet<Integer> preferred = new TreeSet<>();
            for (String partner : partners.get(node))
                if (colors.containsKey(partner) && free.contains(colors.get(partner)))
                    preferred.add(colors.get(partner));
            colors.put(node, preferred.isEmpty() ? free.first() : preferred.first());
        }
    }
    void edge(String first, String second) {
        neighbors.get(first).add(second);
        neighbors.get(second).add(first);
    }
}

import java.util.*;
final class TacParser {
    enum Kind {
        COPY,
        BIN,
        LOAD,
        STORE,
        GOTO,
        IF,
        PARAM,
        CALL,
        RETURN,
        READ,
        PRINT;
        public String toString() { return name().toLowerCase(Locale.ROOT); }
    }
    sealed interface Operand permits Variable, Constant {}
    record Variable(String name) implements Operand {
        public String toString() { return name; }
    }
    record Constant(int value) implements Operand {
        public String toString() { return Integer.toString(value); }
    }
    sealed interface Line permits Label, Instruction {}
    record Label(String name) implements Line {}
    record Expression(Kind kind, String operation, Operand a, Operand b) {
        public String toString() {
            return kind == Kind.LOAD ? operation + "[" + a + "]" : a.toString() + operation + b;
        }
    }
    record Instruction(Kind kind, String destination, Operand a, Operand b, String operation,
                       String name, int count) implements Line {
        List<Integer> operandFields() {
            return switch (kind) {
                case BIN, IF, STORE -> List.of(0, 1);
                case COPY, LOAD, PARAM, PRINT -> List.of(0);
                case RETURN -> a == null ? List.of() : List.of(0);
                default -> List.of();
            };
        }
        Operand operand(int field) { return field == 0 ? a : b; }
        List<String> used() {
            List<String> result = new ArrayList<>();
            for (int field : operandFields())
                if (operand(field) instanceof Variable v)
                    result.add(v.name());
            return result;
        }
        Expression expression() {
            return kind == Kind.BIN ? new Expression(kind, operation, a, b)
            : kind == Kind.LOAD     ? new Expression(kind, name, a, null)
                                    : null;
        }
        Instruction withOperand(int field, Operand operand) {
            return new Instruction(kind, destination, field == 0 ? operand : a,
                                   field == 1 ? operand : b, operation, name, count);
        }
        Instruction withDestination(String destination) {
            return new Instruction(kind, destination, a, b, operation, name, count);
        }
        Instruction withName(String name) {
            return new Instruction(kind, destination, a, b, operation, name, count);
        }
        public String toString() {
            return switch (kind) {
                case COPY -> destination + " = " + a;
                case BIN -> destination + " = " + a + " " + operation + " " + b;
                case LOAD -> destination + " = " + name + "[" + a + "]";
                case STORE -> name + "[" + a + "] = " + b;
                case GOTO -> "goto " + name;
                case IF -> "if " + a + " " + operation + " " + b + " goto " + name;
                case CALL ->
                    (destination == null ? "" : destination + " = ") + "call " + name + " " + count;
                case READ -> "read " + destination;
                case RETURN -> a == null ? "return" : "return " + a;
                default -> kind + " " + a;
            };
        }
    }
    static final class Function {
        final String name;
        final List<String> parameters;
        List<Line> code;
        int temporarySerial, preheaderSerial;
        Function(String name, List<String> parameters, List<Line> code) {
            this.name = name;
            this.parameters = List.copyOf(parameters);
            this.code = new ArrayList<>(code);
        }
        Function copy() { return new Function(name, parameters, code); }
        List<Instruction> instructions() {
            List<Instruction> result = new ArrayList<>();
            for (Line line : code)
                if (line instanceof Instruction instruction)
                    result.add(instruction);
            return result;
        }
    }
    record Array(String name, int size) {}
    record Program(List<Array> arrays, List<Function> functions) {}
    static Instruction copy(String destination, Operand a) {
        return new Instruction(Kind.COPY, destination, a, null, null, null, 0);
    }
    static Operand operand(String word) {
        return word.charAt(0) == '-' || Character.isDigit(word.charAt(0))
            ? new Constant(Integer.parseInt(word))
            : new Variable(word);
    }
    record ArrayOperand(String name, Operand index) {}
    static ArrayOperand arrayOperand(String word) {
        int bracket = word.indexOf('[');
        return new ArrayOperand(word.substring(0, bracket),
                                operand(word.substring(bracket + 1, word.length() - 1)));
    }
    static Instruction instruction(String[] words) {
        String first = words[0];
        switch (first) {
        case "goto":
            return new Instruction(Kind.GOTO, null, null, null, null, words[1], 0);
        case "if":
            return new Instruction(Kind.IF, null, operand(words[1]), operand(words[3]), words[2],
                                   words[5], 0);
        case "param", "print":
            return new Instruction(first.equals("param") ? Kind.PARAM : Kind.PRINT, null,
                                   operand(words[1]), null, null, null, 0);
        case "return":
            return new Instruction(Kind.RETURN, null, words.length == 2 ? operand(words[1]) : null,
                                   null, null, null, 0);
        case "read":
            return new Instruction(Kind.READ, words[1], null, null, null, null, 0);
        case "call":
            return new Instruction(Kind.CALL, null, null, null, null, words[1],
                                   Integer.parseInt(words[2]));
        default:
            break;
        }
        if (first.indexOf('[') >= 0) {
            ArrayOperand array = arrayOperand(first);
            return new Instruction(Kind.STORE, null, array.index(), operand(words[2]), null,
                                   array.name(), 0);
        }
        if (words[2].equals("call"))
            return new Instruction(Kind.CALL, first, null, null, null, words[3],
                                   Integer.parseInt(words[4]));
        if (words.length == 5)
            return new Instruction(Kind.BIN, first, operand(words[2]), operand(words[4]), words[3],
                                   null, 0);
        if (words[2].indexOf('[') >= 0) {
            ArrayOperand array = arrayOperand(words[2]);
            return new Instruction(Kind.LOAD, first, array.index(), null, null, array.name(), 0);
        }
        return copy(first, operand(words[2]));
    }
    static Program parse(String text) {
        List<Array> arrays = new ArrayList<>();
        List<Function> functions = new ArrayList<>();
        Function current = null;
        for (String line : text.lines().toList()) {
            String trimmed = line.trim();
            if (trimmed.isEmpty() || trimmed.startsWith("#"))
                continue;
            String[] words = trimmed.split(" +");
            if (words[0].equals("array"))
                arrays.add(new Array(words[1], Integer.parseInt(words[2])));
            else if (words[0].equals("func")) {
                current = new Function(words[1], Arrays.asList(words).subList(2, words.length),
                                       List.of());
                functions.add(current);
            } else if (words[0].equals("end"))
                current = null;
            else if (words.length == 1 && words[0].endsWith(":"))
                current.code.add(new Label(words[0].substring(0, words[0].length() - 1)));
            else
                current.code.add(instruction(words));
        }
        return new Program(arrays, functions);
    }
    static long calculate(String operation, long first, long second) {
        return switch (operation) {
            case "+" -> first + second;
            case "-" -> first - second;
            case "*" -> first *second;
            case "/" -> first / second;
            case "%" -> first % second;
            case "<" -> first < second ? 1 : 0;
            case "<=" -> first <= second ? 1 : 0;
            case ">" -> first > second ? 1 : 0;
            case ">=" -> first >= second ? 1 : 0;
            case "==" -> first == second ? 1 : 0;
            default -> first != second ? 1 : 0;
        };
    }
    static List<String> functionLines(Function function) {
        List<String> result = new ArrayList<>();
        result.add(
            "func " + function.name +
            (function.parameters.isEmpty() ? "" : " " + String.join(" ", function.parameters)));
        for (Line line : function.code)
            result.add(line instanceof Label label ? label.name() + ":" : "    " + line);
        result.add("end");
        return result;
    }
    static List<String> programLines(Program program) {
        List<String> result = new ArrayList<>();
        for (Array array : program.arrays())
            result.add("array " + array.name() + " " + array.size());
        for (Function function : program.functions()) {
            if (!result.isEmpty())
                result.add("");
            result.addAll(functionLines(function));
        }
        return result;
    }
}
